class Solution {
    public boolean isCircularSentence(String sentence) {
        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            String current = words[i];
            String next = words[(i + 1) % words.length];
            if (current.charAt(current.length() - 1) != next.charAt(0)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isCircularSentence(String sentence) {
        for (int i = 1; i + 1 < sentence.length(); i++) {
            if (sentence.charAt(i) == ' ' && sentence.charAt(i - 1) != sentence.charAt(i + 1)) {
                return false;
            }
        }
        return sentence.charAt(0) == sentence.charAt(sentence.length() - 1);
    }
}

class Solution {
    public boolean isCircularSentence(String sentence) {
        int boundary = sentence.indexOf(' ');
        while (boundary != -1) {
            if (sentence.charAt(boundary - 1) != sentence.charAt(boundary + 1)) {
                return false;
            }
            boundary = sentence.indexOf(' ', boundary + 1);
        }
        return sentence.charAt(0) == sentence.charAt(sentence.length() - 1);
    }
}

class Solution {
    public boolean isCircularSentence(String sentence) {
        String[] words = sentence.split(" ");
        char[] first = new char[words.length];
        char[] last = new char[words.length];
        for (int i = 0; i < words.length; i++) {
            first[i] = words[i].charAt(0);
            last[i] = words[i].charAt(words[i].length() - 1);
        }
        for (int i = 0; i < words.length; i++) {
            if (last[i] != first[(i + 1) % words.length]) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isCircularSentence(String sentence) {
        String[] words = sentence.split(" ");
        return check(words, 0);
    }

    private boolean check(String[] words, int index) {
        if (index == words.length) {
            return true;
        }
        String current = words[index];
        String next = words[(index + 1) % words.length];
        if (current.charAt(current.length() - 1) != next.charAt(0)) {
            return false;
        }
        return check(words, index + 1);
    }
}
